package com.college.attendance.mobile.api;
import android.content.*; import okhttp3.*; import retrofit2.*; import retrofit2.converter.gson.GsonConverterFactory;
public class ApiClient { private static ApiService api; public static ApiService get(Context c){ if(api==null){String base=c.getSharedPreferences("cfg",0).getString("baseUrl","http://10.0.2.2:8080/"); OkHttpClient client=new OkHttpClient.Builder().addInterceptor(chain->{Request o=chain.request();String t=c.getSharedPreferences("auth",0).getString("token","");if(!t.isEmpty())o=o.newBuilder().addHeader("Authorization","Bearer "+t).build();return chain.proceed(o);}).build(); api=new Retrofit.Builder().baseUrl(base.endsWith("/")?base:base+"/").client(client).addConverterFactory(GsonConverterFactory.create()).build().create(ApiService.class);}return api;} }
